import{z as s,x as i,o as e,c as p,q as r,j as n,D as a,d as l,s as o,S as B,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"失败模式分类与收束","description":"","frontmatter":{"title":"失败模式分类与收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pl-map.md","filePath":"llm/pl-map.md","lastUpdated":1791063341000}'),d={name:"llm/pl-map.md"};function F(m,E,D,S,C,h){const t=i("Mermaid");return e(),p("div",null,[E[2]||(E[2]=r('<h1 id="失败模式分类与收束" tabindex="-1">失败模式分类与收束 <a class="header-anchor" href="#失败模式分类与收束" aria-label="Permalink to &quot;失败模式分类与收束&quot;">​</a></h1><div class="epigraph"><p>「答错了」不是数据；上线之后要回答的是坏了哪一环——归因坐标先于归因结论。</p><footer>—— 据本课程七课与 Lightman et al., 2023；Snell et al., 2024 等所引文献整理</footer></div><p><a href="/llm/pl-budget-allocation">上一课</a>把六种花钱的方向并成一张账，按难度分桶各配策略。至此零件齐了：树与回溯、逐步打分、反思、分解、工具计划、预算分配。但线上系统最终被问的不是「钱花在哪」，而是「坏了怎么归因」——只看端到端准确率，六种机制的错误全糊在一个数字里。本课把失败模式分成六族，给每族配可观测信号与诊断顺序。<strong>本课程到此收束。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>推理时系统的失败不是单一变量。搜索剪错、验证器误判、反思复读、分解传错、计划过期、预算烧穿，都会以「答案错了」的同一种表象落到监控里；调参的人却需要知道动哪个旋钮。缺的是一张归因坐标：每族失败有定义、有信号、有对应的修复方向。没有这张表，团队会在验证器上白调一周，而真正的问题是把聚合函数从 \\(\\min\\) 换成了均值。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>六族失败，六组信号。<strong>搜索失败</strong>——剪掉正确前缀、探索不足、分支与深度配错；信号是加预算恢复率：同题同采样换大预算重跑，恢复即搜索侧问题，不恢复是能力问题。<strong>验证失败</strong>——假阳性保护假推理、假阴性剪真链、聚合与训练口径错配；信号是逐步检测的查准查全与聚合口径审计。<strong>反思失败</strong>——复读空转、朝错误归因漂移、记忆污染；信号是<a href="/llm/pl-reflection-design">第三课</a>的答案翻转率与翻转后正确率。<strong>分解失败</strong>——悬空引用、覆盖不全、误差沿回填传播；信号是子问题可解率与覆盖检查通过率。<strong>计划失败</strong>——引用断裂、工具改版、重规划缺失；信号是静态校验打回率与重规划触发率。<strong>预算失败</strong>——饱和区烧钱、截断污染下游；信号是分桶的预算利用率与显式截断占比。</p><p><span class="marginnote">加预算恢复率是六族里最便宜的一个判据：抽样若干错题，翻倍预算重跑即可执行。恢复的题记在搜索与预算头上，不恢复的记在模型头上——这张分账表直接决定下一笔钱投推理侧还是训练侧。</span></p><p><span class="marginnote">数字实例（示意）：抽 100 条错例、翻倍预算重跑，40 条答对了——这 40% 记在搜索与预算侧头上，值得先拧剪枝与分桶；剩 60 条不恢复，再抽其中 20 条人工逐步核对，若多数步子其实是对的、死在最后聚合，那就是验证器误杀。半天人力换来的是「下一个迭代该动哪一层」的排序，而不是又一轮盲调。</span></p>',9)),(e(),n(B,null,{default:a(()=>[o(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ERR%5B%22%E9%94%99%E4%BE%8B%E8%BF%9B%E5%85%A5%E5%BD%92%E5%9B%A0%22%5D%20--%3E%20SIG%7B%22%E5%85%AD%E6%97%8F%E4%BF%A1%E5%8F%B7%E5%88%86%E8%AF%8A%22%7D%0A%20%20SIG%20--%3E%20S1%5B%22%E6%90%9C%E7%B4%A2%EF%BC%9A%E5%8A%A0%E9%A2%84%E7%AE%97%E6%81%A2%E5%A4%8D%E7%8E%87%22%5D%0A%20%20SIG%20--%3E%20S2%5B%22%E9%AA%8C%E8%AF%81%EF%BC%9A%E9%80%90%E6%AD%A5%E6%9F%A5%E5%87%86%E6%9F%A5%E5%85%A8%22%5D%0A%20%20SIG%20--%3E%20S3%5B%22%E5%8F%8D%E6%80%9D%EF%BC%9A%E7%BF%BB%E8%BD%AC%E7%8E%87%E4%B8%8E%E7%BF%BB%E8%BD%AC%E5%90%8E%E6%AD%A3%E7%A1%AE%E7%8E%87%22%5D%0A%20%20SIG%20--%3E%20S4%5B%22%E5%88%86%E8%A7%A3%EF%BC%9A%E5%8F%AF%E8%A7%A3%E7%8E%87%E4%B8%8E%E8%A6%86%E7%9B%96%E7%8E%87%22%5D%0A%20%20SIG%20--%3E%20S5%5B%22%E8%AE%A1%E5%88%92%EF%BC%9A%E6%89%93%E5%9B%9E%E7%8E%87%E4%B8%8E%E9%87%8D%E8%A7%84%E5%88%92%E8%A7%A6%E5%8F%91%E7%8E%87%22%5D%0A%20%20SIG%20--%3E%20S6%5B%22%E9%A2%84%E7%AE%97%EF%BC%9A%E5%88%A9%E7%94%A8%E7%8E%87%E4%B8%8E%E6%88%AA%E6%96%AD%E5%8D%A0%E6%AF%94%22%5D%0A%20%20S1%20--%3E%20FIX%5B%22%E5%AE%9A%E4%BD%8D%E6%97%8B%E9%92%AE%EF%BC%9A%E5%89%AA%E6%9E%9D%E5%8F%82%E6%95%B0%20%2F%20%E6%89%93%E5%88%86%E5%99%A8%20%2F%20%E8%A7%A6%E5%8F%91%E5%99%A8%20%2F%20%E6%8E%A5%E5%8F%A3%20%2F%20%E8%AE%A1%E5%88%92%20%2F%20%E5%88%86%E6%A1%B6%22%5D%0A%20%20S2%20--%3E%20FIX%0A%20%20S3%20--%3E%20FIX%0A%20%20S4%20--%3E%20FIX%0A%20%20S5%20--%3E%20FIX%0A%20%20S6%20--%3E%20FIX%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[l("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"诊断有顺序，因为失败会伪装。验证器先查：它同时喂搜索（第二课的剪枝）与反思（第三课的门控），校准一坏，两处一起坏，且表现为搜索侧的「探索不足」。搜索参数次查：换聚合、换 \\(c\\)、换闸门配比，都是配置级改动。预算最后查：分桶利用率会暴露「把难题桶的钱匀给了易题桶」的错配。评测必须双拆：按难度桶拆，按失败族拆；只报平均准确率的推理系统，等于把六族失败混装进一个未知数。上线的顺序随之固定：先钉真值通道（可核对域的终局校验），再配预算分桶，再开搜索与反思的触发器，最后挂六族信号的面板——顺序倒了，前面每一步的收益都无法归因。",-1)),E[5]||(E[5]=A("p",null,[A("span",{class:"marginnote"},"「假阳性 / 假阴性」翻译成验证器的话：假阳性是坏推理被打了高分——「罪犯被放行」，错误推理一路畅通地进了最终答案；假阴性是好链被打低分——「好人被冤枉」，正确的探索分支被剪枝丢掉。前者坏答案，后者浪费钱，而两者往往来自同一个没校准好的打分器。")],-1)),(e(),n(B,null,{default:a(()=>[o(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAL%5B%22%E9%AA%8C%E8%AF%81%E5%99%A8%E6%A0%A1%E5%87%86%E5%87%BA%E9%94%99%22%5D%20--%3E%20M1%5B%22%E6%90%9C%E7%B4%A2%E4%BE%A7%EF%BC%9A%E5%A5%BD%E9%93%BE%E8%A2%AB%E5%89%AA%E6%8E%89%22%5D%0A%20%20CAL%20--%3E%20M2%5B%22%E5%8F%8D%E6%80%9D%E9%97%A8%E6%8E%A7%EF%BC%9A%E5%A5%BD%E7%AD%94%E6%A1%88%E8%A2%AB%E7%BF%BB%E6%8E%89%22%5D%0A%20%20M1%20--%3E%20LOOK%5B%22%E8%A1%A8%E8%B1%A1%E4%BC%AA%E8%A3%85%E6%88%90%EF%BC%9A%E6%8E%A2%E7%B4%A2%E4%B8%8D%E8%B6%B3%20%2F%20%E5%8F%8D%E6%80%9D%E7%A9%BA%E8%BD%AC%22%5D%0A%20%20M2%20--%3E%20LOOK%0A%20%20LOOK%20--%3E%20WRONG%5B%22%E5%85%88%E8%B0%83%E5%89%AA%E6%9E%9D%E4%B8%8E%E8%A7%A6%E5%8F%91%E5%99%A8%20%3D%20%E7%99%BD%E8%B0%83%E4%B8%80%E5%91%A8%22%5D%0A%20%20CAL%20--%3E%20CHECK%5B%22%E5%85%88%E5%AE%A1%E8%AE%A1%E8%81%9A%E5%90%88%E5%8F%A3%E5%BE%84%E4%B8%8E%E6%9F%A5%E5%87%86%E6%9F%A5%E5%85%A8%22%5D%0A%20%20CHECK%20--%3E%20REAL%5B%22%E7%9C%9F%E6%AD%A3%E7%9A%84%E6%97%8B%E9%92%AE%EF%BC%9A%E9%AA%8C%E8%AF%81%E5%99%A8%E6%A0%A1%E5%87%86%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>失败常复合：一个错例可以同时是「PRM 假阳性」加「难题桶预算不足」，分类是归因坐标，不是互斥判决，抽样深查永远需要。开放域没有可靠真值通道时，六族里只有计划与预算两族能硬观测，其余只能代理指标。最后重申全课程的地基：评估器与校验器的校准决定搜索与反思的上限，<a href="/llm/verifier-bottleneck">验证器瓶颈</a>不会因为搜索更花哨而消失；预算的收益封顶于基座能力，持续超支的桶该回流训练。<strong>本课程到此收束。</strong></p><p><span class="marginnote">常见误区：初学者容易只盯平均准确率——两个系统平均分同为 70%，一个错例全堆在难题桶（该调预算分桶），一个均匀撒在所有桶（该查验证器与搜索），修复动作完全不同。平均数把这两种病折叠成同一个数字；按桶、按族拆开，数字才开始说话。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>六族失败各有定义与信号：搜索、验证、反思、分解、计划、预算；「答错」必须落到族上。</li><li>加预算恢复率是最便宜的判据：恢复记推理侧，不恢复记训练侧。</li><li>诊断顺序：先验证器校准，再搜索参数，再预算分桶；顺序倒了一切无法归因。</li><li>评测双拆：按难度桶、按失败族；平均准确率不是运维接口。</li><li>真值通道、预算分桶、触发器、监控面板按此顺序上线。</li><li>出处：据本课程七课整理；核心文献 Lightman et al., <em>Let&#39;s Verify Step by Step</em>, 2023；Yao et al., <em>Tree of Thoughts</em>, NeurIPS 2023；Shinn et al., <em>Reflexion</em>, NeurIPS 2023；Snell et al., 2024。</li></ul>',5))])}const u=s(d,[["render",F]]);export{f as __pageData,u as default};
